```cpp
#include <iostream>
#include <string>
#include <regex>

std::string convertReducedToHtml(const std::string& reducedText) {
    std::string htmlText;

    // Convert ampersands (&) to HTML entity (&amp;)
    htmlText = std::regex_replace(reducedText, std::regex("&"), "&amp;");

    // Convert angle brackets (< and >) to HTML entities (&lt; and &gt;)
    htmlText = std::regex_replace(htmlText, std::regex("<"), "&lt;"); 
